-- LEVEL UP WITH ALAA — BAC 2027
-- seed_import.sql v2 — generated by scripts/generate_seed.py from level-up-132-days-schema.json
-- Same values as v1. Safe to re-run: never duplicates rows and never overwrites
-- content edited from the admin panel (titles, descriptions, videos, resources, checklist text).
-- Run AFTER supabase/schema.sql.

begin;

-- program_days
on conflict (day_number) do update set month = excluded.month;

-- program_tasks (insert-only: admin edits are preserved)
on conflict (id) do nothing;

-- program_checklist_items (insert-only: admin edits are preserved)
on conflict (id) do nothing;

-- weekly_reviews
on conflict (week_number) do update set from_day=excluded.from_day, to_day=excluded.to_day, max_stars=excluded.max_stars;

-- monthly_reviews
on conflict (month_number) do update set from_day=excluded.from_day, to_day=excluded.to_day, max_stars=excluded.max_stars;

-- final_check_metrics
on conflict (label) do update set value=excluded.value, target=excluded.target;

-- self-check: abort (and roll back) if anything is missing
do $$ begin
  if (select count(*) from public.program_days) <> 132 then raise exception 'seed check failed: program_days'; end if;
  if (select count(*) from public.program_tasks) <> 396 then raise exception 'seed check failed: program_tasks'; end if;
  if (select count(*) from public.program_checklist_items) <> 335 then raise exception 'seed check failed: program_checklist_items'; end if;
  if (select count(*) from public.weekly_reviews) <> 19 then raise exception 'seed check failed: weekly_reviews'; end if;
  if (select count(*) from public.monthly_reviews) <> 4 then raise exception 'seed check failed: monthly_reviews'; end if;
  raise notice 'seed OK: 132 days, 396 tasks, 335 checklist items';
end $$;

commit;
